var anchors = __find("Dinner");
var recipes = [];
var seen = {};
document.querySelectorAll('a').forEach(function(a) {
  var href = a.getAttribute('href');
  var txt = a.textContent.trim();
  if (href && href.indexOf('allrecipes.com/recipe/') === 0 && txt.length > 5 && !seen[href]) {
    seen[href] = true;
    recipes.push({ title: txt, url: href });
  }
});
return recipes.slice(0, 30);

var recipes = [];
var seen = {};
document.querySelectorAll('a').forEach(function(a) {
  var href = a.getAttribute('href');
  var txt = a.textContent.trim();
  if (href && href.indexOf('/recipe/') >= 0 && txt.length > 5 && txt.length < 200 && !seen[href]) {
    seen[href] = true;
    recipes.push({ title: txt.substring(0, 100), url: href });
  }
});
return recipes.slice(0, 30);

var anchors = document.querySelectorAll('a');
var sample = [];
for (var i = 0; i < Math.min(10, anchors.length); i++) {
  var a = anchors[i];
  sample.push({
    href: a.getAttribute('href'),
    text: a.textContent.trim().substring(0, 60)
  });
}
return {
  totalAnchors: anchors.length,
  sample: sample,
  pageURL: window.location.href
};

var anchors = document.querySelectorAll('a');
var recipeLinks = [];
var seen = {};
for (var i = 0; i < anchors.length; i++) {
  var a = anchors[i];
  var href = a.getAttribute('href');
  var txt = a.textContent.trim();
  // Recipe pages are /recipe/XXXXX/ (singular) - look for ones that aren't category pages
  if (href && /\/\d+\/[a-z0-9-]+\/?$/.test(href) && txt.length > 5 && txt.length < 150 && !seen[href]) {
    seen[href] = true;
    recipeLinks.push({ title: txt, url: href });
  }
}
return recipeLinks.slice(0, 30);

var cards = document.querySelectorAll('#mntl-card-list-items_5-0, #mntl-card-list-items_6-0, #mntl-card-list-items_7-0');
var results = [];
for (var i = 0; i < cards.length; i++) {
  var card = cards[i];
  var href = card.getAttribute('href');
  var txt = card.textContent.trim();
  results.push({ title: txt.substring(0, 200), url: href });
}
return results;

var featured = document.getElementById('mntl-five-post__featured_1-0');
var card1 = document.getElementById('mntl-card-list-items_1-0');
var card2 = document.getElementById('mntl-card-list-items_2-0');
var card3 = document.getElementById('mntl-card-list-items_3-0');
var card4 = document.getElementById('mntl-card-list-items_4-0');

function getInfo(el) {
  if (!el) return null;
  var titleEl = el.querySelector('.card__title, h3, h2, .mntl-card-list-items__title, [class*="title"]');
  var heading = titleEl ? titleEl.textContent.trim() : null;
  var imgAlt = el.querySelector('img') ? el.querySelector('img').getAttribute('alt') : null;
  return {
    href: el.getAttribute('href'),
    heading: heading,
    imgAlt: imgAlt,
    fullText: el.textContent.trim().substring(0, 200)
  };
}

return {
  featured: getInfo(featured),
  card1: getInfo(card1),
  card2: getInfo(card2),
  card3: getInfo(card3),
  card4: getInfo(card4)
};
